public class Test
{
    const bool ct = true;

    public static int Main()
    {
        var a = (true & null) ?? null;  // CS0458
        if (((null & true) == null))   // CS0458
            return 0;

        var b = !(null | false);      // CS0458
        if ((false | null) != null)   // CS0458
            return 1;

        const bool cf = false;
        var d = ct & null ^ null;  // CS0458 - Roslyn Warn this ONLY
        d ^= !(null | cf);        // CS0458

        return -1;
    }
}

